HandwritingRecognizerAsyncWaiter::HandwritingRecognizerAsyncWaiter(
    HandwritingRecognizer* proxy) : proxy_(proxy) {}

HandwritingRecognizerAsyncWaiter::~HandwritingRecognizerAsyncWaiter() = default;

void HandwritingRecognizerAsyncWaiter::Recognize(
    HandwritingRecognitionQueryPtr query, HandwritingRecognizerResultPtr* out_result) {
  base::RunLoop loop;
  proxy_->Recognize(std::move(query),
      base::BindOnce(
          [](base::RunLoop* loop,
             HandwritingRecognizerResultPtr* out_result
,
             HandwritingRecognizerResultPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}





